'use client';
import { motion } from 'framer-motion';
import { useWindowStore, AppId } from '@/store/useWindowStore';
import { useSettingsStore } from '@/store/useSettingsStore';
import React, { useEffect, useState } from 'react';

interface Props {
  id: AppId;
  children: React.ReactNode;
  defaultWidth?: number | string;
  defaultHeight?: number | string;
}

export default function DraggableWindow({ id, children, defaultWidth = 750, defaultHeight = 500 }: Props) {
  const windowState = useWindowStore((state) => state.windows[id]);
  const { closeApp, minimizeApp, maximizeApp, focusApp } = useWindowStore();
  const { themeMode } = useSettingsStore();

  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);

  if (!mounted || !windowState.isOpen || windowState.isMinimized) return null;

  const isLight = themeMode === 'light';

  return (
    <motion.div
      drag={!windowState.isMaximized}
      dragMomentum={false}
      onMouseDown={() => focusApp(id)}
      initial={{ scale: 0.9, opacity: 0, y: 20 }}
      animate={{ 
        scale: 1, 
        opacity: 1,
        y: 0,
        width: windowState.isMaximized ? '100vw' : defaultWidth,
        height: windowState.isMaximized ? '100vh' : defaultHeight,
        top: windowState.isMaximized ? 0 : '10%',
        left: windowState.isMaximized ? 0 : '20%',
      }}
      exit={{ scale: 0.9, opacity: 0, y: 20 }}
      transition={{ type: 'spring', damping: 25, stiffness: 250 }}
      style={{ zIndex: windowState.zIndex }}
      className={`absolute flex flex-col overflow-hidden backdrop-blur-3xl transition-colors
      ${isLight 
        ? 'bg-white/70 border border-slate-200/60 shadow-[0_20px_50px_rgba(0,0,0,0.15)]' 
        : 'bg-black/60 border border-white/[0.15] shadow-[0_30px_60px_rgba(0,0,0,0.6),inset_0_0_0_1px_rgba(255,255,255,0.1)]'}
      ${windowState.isMaximized ? 'rounded-none' : 'rounded-2xl'}`}
    >
      {/* Premium Mac-style Title Bar */}
      <div 
        className={`h-12 flex items-center justify-between px-4 border-b transition-colors
        ${isLight ? 'bg-slate-50/50 border-slate-200/50' : 'bg-white/[0.03] border-white/[0.08]'}
        ${windowState.isMaximized ? '' : 'cursor-grab active:cursor-grabbing'}`}
        onPointerDown={(e) => focusApp(id)}
      >
        <div className="flex space-x-2 w-20">
          <button onClick={(e) => { e.stopPropagation(); closeApp(id); }} className="w-3.5 h-3.5 rounded-full bg-[#ff5f56] border border-[#e0443e] hover:bg-[#ff5f56]/80 flex items-center justify-center shadow-inner" />
          <button onClick={(e) => { e.stopPropagation(); minimizeApp(id); }} className="w-3.5 h-3.5 rounded-full bg-[#ffbd2e] border border-[#dea123] hover:bg-[#ffbd2e]/80 flex items-center justify-center shadow-inner" />
          <button onClick={(e) => { e.stopPropagation(); maximizeApp(id); }} className="w-3.5 h-3.5 rounded-full bg-[#27c93f] border border-[#1aab29] hover:bg-[#27c93f]/80 flex items-center justify-center shadow-inner" />
        </div>
        <div className={`text-xs font-bold tracking-[0.2em] select-none flex-1 text-center pr-20 uppercase transition-colors
          ${isLight ? 'text-slate-500' : 'text-white/60'}`}>
          {windowState.title}
        </div>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-auto relative rounded-b-2xl">
        {children}
      </div>
    </motion.div>
  );
}

