export default function Taskbar() {
  const { windows, openApp, focusApp, minimizeApp, highestZIndex } = useWindowStore();
  const { themeMode, accentColor } = useSettingsStore();
  const [time, setTime] = useState<string>('');
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
    const updateTime = () => setTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    updateTime();
    const interval = setInterval(updateTime, 1000);
    return () => clearInterval(interval);
  }, []);

  const handleAppClick = (id: AppId, title: string) => {
    const win = windows[id];
    if (!win.isOpen) {
      openApp(id, title);
    } else if (win.isMinimized) {
      focusApp(id);
    } else if (win.zIndex === highestZIndex) {
      minimizeApp(id);
    } else {
      focusApp(id);
    }
  };

  if (!mounted) return null;

  const isLight = themeMode === 'light';

  return (
    <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-[999]">
      {/* macOS style floating dock */}
      <div className={`flex items-center space-x-4 backdrop-blur-2xl px-4 py-3 rounded-3xl transition-colors
        ${isLight ? 'bg-white/40 border border-slate-200/50 shadow-[0_8px_32px_rgba(0,0,0,0.1)]' : 'bg-white/10 border border-white/20 shadow-[0_8px_32px_rgba(0,0,0,0.5)]'}`}
      >
        {apps.map((app) => {
          const isOpen = windows[app.id].isOpen;
          const isFocused = isOpen && !windows[app.id].isMinimized && windows[app.id].zIndex === highestZIndex;

          return (
            <motion.button
              whileHover={{ scale: 1.25, y: -10 }}
              whileTap={{ scale: 0.95 }}
              key={app.id}
              onClick={() => handleAppClick(app.id, app.title)}
              className={`w-12 h-12 rounded-2xl flex flex-col items-center justify-center cursor-pointer relative group transition-colors shadow-lg border
                ${isOpen ? `bg-gradient-to-br ${accentColor} border-white/30` : isLight ? 'bg-white/40 border-white/40 hover:bg-white/60' : 'bg-white/5 border-white/10 hover:bg-white/20'}`}
            >
              <app.icon size={24} className={`${isLight && !isOpen ? 'text-slate-700' : 'text-white'} drop-shadow-md transition-colors`} />

              {/* Active Indicator dot */}
              {isOpen && (
                <div className={`absolute -bottom-2.5 w-1.5 h-1.5 rounded-full transition-all ${isFocused ? (isLight ? 'bg-slate-800' : 'bg-white shadow-[0_0_8px_rgba(255,255,255,0.8)]') : (isLight ? 'bg-slate-400' : 'bg-white/50')}`} />
              )}

              {/* Tooltip */}
              <div className={`absolute -top-12 opacity-0 group-hover:opacity-100 transition-opacity text-xs px-3 py-1.5 rounded-md backdrop-blur-md pointer-events-none whitespace-nowrap shadow-xl
                ${isLight ? 'bg-white/90 text-slate-800 border border-slate-200' : 'bg-black/70 text-white border border-white/10'}`}>
                {app.title}
              </div>
            </motion.button>
          );
        })}

        {/* Divider */}
        <div className={`w-[1px] h-10 mx-2 ${isLight ? 'bg-slate-300' : 'bg-white/20'}`} />

        {/* Time Widget */}
        <div className={`flex flex-col items-center justify-center px-2 select-none ${isLight ? 'text-slate-800' : 'text-white/90'}`}>
          <span className="font-mono text-sm tracking-widest">{time.split(' ')[0]}</span>
          <span className={`text-[10px] uppercase font-bold tracking-wider ${isLight ? 'text-slate-500' : 'text-white/50'}`}>{time.split(' ')[1]}</span>
        </div>
      </div>
    </div>
  );
}

